begin;
-- Bases 020501 de janeiro a setembro/2026, isoladas do OOR retroativo.
-- Máximo operacional respeita o objetivo de cinco dias; cálculo bruto mantido em auditoria.
create temporary table quarter_receipts(code text,sku text,stock_avg_qty numeric,pull_qty numeric,raw_max_qty numeric,stock_recorded boolean) on commit drop;
select v.id,p.sku_code,'GENERATE',jsonb_build_object('method','quarterly-complete-020501-2026-v3','stock_avg_qty',r.stock_avg_qty,'pull_qty',r.pull_qty,'raw_max_qty',r.raw_max_qty,'stock_recorded',r.stock_recorded,'objective_floor_applied',r.raw_max_qty<p.objective_qty,'previous_item',to_jsonb(p),'history_preserved',true)
from stock_policy_items p join stock_policy_versions v on v.id=p.version_id join quarter_receipts r on r.code=v.code and r.sku=p.sku_code
where v.status='draft' and v.oor_enabled=false;
update stock_policy_items p set max_qty=greatest(r.raw_max_qty,p.objective_qty),over_qty=greatest(r.raw_max_qty,p.objective_qty),
 max_days=greatest(r.raw_max_qty,p.objective_qty)/p.avg_daily_qty,
 max_hl=greatest(r.raw_max_qty,p.objective_qty)*p.avg_daily_hl/p.avg_daily_qty,
 policy_source='TRIMESTRAL_COMPLETA_020501_2026',review_flags='[]'::jsonb,review_note=null,
 source_file=coalesce(p.source_file,'')||' | 01- Planilha do Financeiro.zip (020501/2026)',
 suggestion_basis='Trimestre anterior; dias efetivos no estoque. Mínimo 3 dias e objetivo 5 dias. Máximo = maior entre estoque médio + puxada acumulada e objetivo de 5 dias, em unidades compatíveis. Ausência do SKU no estoque completo = estoque registrado zero. Entradas 251 e 314; armazém e depósito 1; duplicatas removidas. Litros e dúzias mantidos nas unidades da venda. Ativos de giro excluídos. Fontes completas de 020501/2026 usadas apenas nesta política; OOR histórico preservado.',updated_at=now()
from stock_policy_versions v,quarter_receipts r where p.version_id=v.id and v.code=r.code and p.sku_code=r.sku and v.status='draft' and v.oor_enabled=false and p.avg_daily_qty>0;
update stock_policy_versions v set calculation_metadata=v.calculation_metadata||jsonb_build_object(
 'readiness','ready','missing','[]'::jsonb,'pending_maximum_items',0,
 'pull_days',case v.code when 'T2/2026' then 76 when 'T3/2026' then 74 else 79 end,
 'pull_source','01- Planilha do Financeiro.zip',
 'pull_source_summary','[{"file": "01.JANEIRO.xlsx", "rows": 1268, "days": 26, "start": "2026-01-02", "end": "2026-01-31", "operations": {"251": 670, "314": 598}}, {"file": "02. FEVEREIRO..xlsx", "rows": 1003, "days": 23, "start": "2026-02-02", "end": "2026-02-28", "operations": {"251": 543, "314": 460}}, {"file": "03. MARÇO.xlsx", "rows": 1161, "days": 27, "start": "2026-03-02", "end": "2026-03-31", "operations": {"251": 626, "314": 535}}, {"file": "04. ABRIL.xlsx", "rows": 822, "days": 23, "start": "2026-04-01", "end": "2026-04-30", "operations": {"251": 438, "314": 384}}, {"file": "05. MAIO.xlsx", "rows": 1111, "days": 24, "start": "2026-05-02", "end": "2026-05-30", "operations": {"251": 588, "314": 523}}, {"file": "06. JUNHO.xlsx", "rows": 843, "days": 27, "start": "2026-06-01", "end": "2026-06-30", "operations": {"251": 448, "314": 395}}, {"file": "07. JULHO.xlsx", "rows": 829, "days": 25, "start": "2026-07-01", "end": "2026-07-31", "operations": {"251": 434, "314": 395}}, {"file": "08. AGOSTO.xlsx", "rows": 982, "days": 26, "start": "2026-08-01", "end": "2026-08-31", "operations": {"251": 518, "314": 464}}, {"file": "09.SETEMBRO.xlsx", "rows": 928, "days": 28, "start": "2026-09-01", "end": "2026-09-30", "operations": {"251": 486, "314": 442}}, {"file": "10.OUTUBRO..xlsx", "rows": 124, "days": 4, "start": "2026-10-01", "end": "2026-10-05", "operations": {"251": 65, "314": 59}}]'::jsonb,
 'duplicate_receipt_rows_removed',6,
 'objective_floor_items',(select count(*) from quarter_receipts r join stock_policy_items p on p.version_id=v.id and p.sku_code=r.sku where r.code=v.code and r.raw_max_qty<p.objective_qty),
 'maximum_rule','max(estoque médio + puxada acumulada, objetivo de 5 dias)',
 'oor_history_preserved',true),method_version='quarterly-complete-020501-2026-v3',updated_at=now()
where v.code in('T2/2026','T3/2026','T4/2026') and v.status='draft' and v.oor_enabled=false;
select id,'GENERATE',jsonb_build_object('source','01- Planilha do Financeiro.zip','readiness','ready','oor_enabled',false,'days_worked',calculation_metadata->'days_worked','objective_floor_items',calculation_metadata->'objective_floor_items','history_preserved',true)
from stock_policy_versions where code in('T2/2026','T3/2026','T4/2026') and status='draft' and oor_enabled=false;
commit;
